SELECT cd_ret.cd_gender, cd_ret.cd_education_status, COUNT(cr.cr_order_number) AS num_returns, SUM(cr.cr_return_amt_inc_tax) AS total_return_amount, AVG(cr.cr_net_loss) AS avg_net_loss, AVG(cd_r.cd_purchase_estimate) AS avg_refunded_purchase_estimate, RANK() OVER (ORDER BY SUM(cr.cr_return_amt_inc_tax) DESC) AS amount_rank, CASE WHEN SUM(cr.cr_return_amt_inc_tax) > 5000 THEN 'High' WHEN SUM(cr.cr_return_amt_inc_tax) BETWEEN 2000 AND 5000 THEN 'Medium' ELSE 'Low' END AS return_category FROM catalog_returns cr JOIN customer_demographics cd_ret ON cr.cr_returning_cdemo_sk = cd_ret.cd_demo_sk JOIN customer_demographics cd_r ON cr.cr_refunded_cdemo_sk = cd_r.cd_demo_sk JOIN household_demographics hd_ret ON cr.cr_returning_hdemo_sk = hd_ret.hd_demo_sk GROUP BY cd_ret.cd_gender, cd_ret.cd_education_status HAVING COUNT(cr.cr_order_number) >= 10 ORDER BY total_return_amount DESC LIMIT 15
